/** Domain types shared by server and client. No runtime code here. */

export type Task = {
  id: string;
  title: string;
  description?: string;
  /** ISO-8601 timestamp, e.g. "2026-10-31T13:20:00.000Z" */
  createdAt: string;
};

/** What a caller provides to create a task; the id is generated by the repository. */
export type NewTask = Omit<Task, "id">;

export type TaskPage = {
  items: Task[];
  /** Opaque cursor for the next page, or `null` when this is the last page. */
  nextCursor: number | null;
  /** Total number of tasks, independent of pagination. */
  total: number;
};
